import{_ as i,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-11-11 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-11-11 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-11-11T00:00:00.000Z","updated":"2019-11-16T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","内存管理","PG Autoscaler"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-11_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-11-11_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-11-11_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function s(n,l,a,_,p,g){return e(),t("div",null,[...l[0]||(l[0]=[o("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 多位Ceph研发人员，包括Mishkin、Mia、Young Waller、Eric、Jason、Adam、Ben、Josh、Ilya等。</p><p><strong>会议主题</strong>：</p><ul><li>Ceph存储系统近期更新及讨论</li><li>分布式存储Ceph的性能优化</li><li>内存管理策略讨论</li></ul><p><strong>会议关键细节</strong>：</p><ol><li><p><strong>Ceph存储系统近期更新</strong>：</p><ul><li>PG Autoscaler更新：增加了最小默认PG数量，从4个增加到16个，以提升并行性和可扩展性。</li><li>RBD更新：实现了RBD复制的日志核心代码的第一部分。</li><li>OSD更新：增强了OSD的亲和性阶段。</li><li>MDS更新：MDS机会和MDS缓存内存限制得到更新。</li><li>RGW更新：将额外的过滤功能移动到CLS代码中。</li></ul></li><li><p><strong>性能优化讨论</strong>：</p><ul><li>透明大页面（THP）问题：讨论了THP可能导致内存使用过高的问题，并考虑通过限制THP使用来解决这个问题。</li><li>内存分配器优化：讨论了TC malloc内存分配器的性能问题，并考虑使用内存池或对象池来优化内存分配。</li><li>缓冲区管理：讨论了缓冲区管理的最佳实践，并考虑使用scatter-gather I/O来减少缓冲区管理的开销。</li></ul></li><li><p><strong>决定的事项</strong>：</p><ul><li>接受新的PG Autoscaler默认值。</li><li>禁用novelist的arm range和novelist。</li><li>降低默认的max OMAP增加量。</li><li>实施Eric的PR以减少bucket列表中的chard条目数。</li><li>继续测试和优化THP和TC malloc。</li><li>考虑使用内存池或对象池来优化内存分配。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续跟进THP和TC malloc的优化。</li><li>完成RBD复制的日志核心代码。</li><li>实施新的PG Autoscaler默认值。</li><li>禁用novelist的arm range和novelist。</li><li>降低默认的max OMAP增加量。</li><li>完成其他待办事项。</li></ul></li></ol><p><strong>会议总结</strong>：</p><p>本次会议讨论了Ceph存储系统近期更新、性能优化策略以及内存管理策略。会议达成了多项决定，并制定了后续行动计划，以进一步提升Ceph存储系统的性能和稳定性。</p>",9)])])}const m=i(r,[["render",s]]);export{c as __pageData,m as default};
